def write_site(domain, template):
    root = os.path.join(WWW_DIR, domain)
    os.makedirs(os.path.join(root, ".well-known", "acme-challenge"), exist_ok=True)
    for fn, body in site_html(domain, template).items():
        write_file(os.path.join(root, fn), body, 0o644)
    for d in (WWW_DIR, root):
        try:
            os.chmod(d, 0o755)
        except OSError:
            pass
    return root


def nginx_conf(domain, s, with_tls):
    root = os.path.join(WWW_DIR, domain)
    full, key = cert_paths(domain)
    common = ("    root %s;\n    index index.html;\n    error_page 404 /404.html;\n    server_tokens off;\n"
              "    location /.well-known/acme-challenge/ { root %s; }\n    location / { try_files $uri $uri/ =404; }\n") % (root, root)
    out = "# generated by NETIFAY - decoy site for %s\n" % domain
    if s.get("http80", True):
        out += "server {\n    listen 80;\n    server_name %s;\n%s}\n" % (domain, common)
    if with_tls:
        host = "127.0.0.1:" if s.get("https_local") else ""
        out += ("server {\n    listen %s%d ssl;\n    http2 on;\n    server_name %s;\n    ssl_certificate %s;\n    ssl_certificate_key %s;\n"
                "    ssl_protocols TLSv1.2 TLSv1.3;\n    ssl_session_cache shared:NETIFAY:10m;\n%s}\n") % (host, s["https_port"], domain, full, key, common)
    if s.get("fallback_port"):
        out += "server {\n    listen 127.0.0.1:%d;\n    server_name %s _;\n%s}\n" % (s["fallback_port"], domain, common)
    return out


def nginx_apply(domain, s, with_tls):
    path = os.path.join(NGINX_DIR, "netifay-%s.conf" % domain)
    old = read_file(path)
    text = nginx_conf(domain, s, with_tls)
    # older nginx (< 1.25.1) does not know `http2 on;`
    rc, ver = run(["nginx", "-v"])
    m = re.search(r"nginx/(\d+)\.(\d+)\.(\d+)", ver)
    if m and tuple(int(x) for x in m.groups()) < (1, 25, 1):
        text = text.replace("    http2 on;\n", "").replace(" ssl;\n", " ssl http2;\n")
    write_file(path, text, 0o644)
    rc, out = run(["nginx", "-t"])
    if rc != 0:
        if old:
            write_file(path, old, 0o644)
        else:
            os.remove(path)
        raise ApiError("تنظیم nginx معتبر نیست: %s" % out.strip()[-300:])
    run(["systemctl", "enable", "nginx"])
    rc, out = run(["systemctl", "reload-or-restart", "nginx"], timeout=60)
    if rc != 0:
        raise ApiError("nginx اجرا نشد: %s" % out.strip()[-300:])


def a_ssl_status(p):
    sites = sites_load()
    names = sorted(set(sites) | set(d for d in (os.listdir(os.path.join(LE_DIR, "live"))
                                                if os.path.isdir(os.path.join(LE_DIR, "live")) else [])
                                    if DOMAIN_RE.match(d)))
    items = []
    for d in names:
        s_ = sites.get(d, {})
        items.append({"domain": d, "cert": cert_info(d), "site": bool(s_), "template": s_.get("template", ""),
                      "method": s_.get("method", ""), "https_port": s_.get("https_port", 0),
                      "https_local": bool(s_.get("https_local")), "fallback_port": s_.get("fallback_port", 0),
                      "ip": s_.get("ip", ""), "created": s_.get("created", 0)})
    nginx_state = run(["systemctl", "is-active", "nginx"])[1].strip() if shutil.which("nginx") else ""
    return {"deps": ssl_deps(), "ip": public_ipv4(), "items": items, "nginx": nginx_state,
            "cf_saved": os.path.isfile(CF_INI), "templates": list(SITE_TEMPLATES)}


def a_ssl_deps_install(p):
    with LOCK:
        if not shutil.which("apt-get"):
            raise ApiError("این سرور apt ندارد؛ nginx و certbot را دستی نصب کنید")
        rc, out = run(["apt-get", "update", "-y"], timeout=300, env={"DEBIAN_FRONTEND": "noninteractive"})
        rc, out = run(["apt-get", "install", "-y", "nginx", "certbot", "python3-certbot-dns-cloudflare"],
                      timeout=600, env={"DEBIAN_FRONTEND": "noninteractive"})
        if rc != 0:
            raise ApiError("نصب ناموفق بود: %s" % out.strip()[-400:])
        # the stock default site would answer any unknown name on port 80; keep nginx quiet otherwise
        for f in ("/etc/nginx/sites-enabled/default",):
            try:
                os.remove(f)
            except OSError:
                pass
        run(["systemctl", "enable", "--now", "nginx"], timeout=60)
    return {"deps": ssl_deps()}


def _site_cleanup(domain):
    try:
        os.remove(os.path.join(NGINX_DIR, "netifay-%s.conf" % domain))
    except OSError:
        pass
    shutil.rmtree(os.path.join(WWW_DIR, domain), ignore_errors=True)
    run(["systemctl", "reload", "nginx"], timeout=30)


def a_ssl_issue(p):
    domain = str(p.get("domain") or "").strip().lower().rstrip(".")
    if not DOMAIN_RE.match(domain):
        raise ApiError("دامنه نامعتبر است")
    ip = v_ipv4(p.get("ip") or public_ipv4(), "IP سرور")
    method = p.get("method") if p.get("method") in ("http", "cloudflare") else "http"
    email = str(p.get("email") or "").strip()
    if email and not EMAIL_RE.match(email):
        raise ApiError("ایمیل نامعتبر است")
    template = p.get("template") if p.get("template") in SITE_TEMPLATES else "blog"
    https_port = v_int(p.get("https_port"), "پورت HTTPS سایت", 1, 65535, 443)
    https_local = bool(p.get("https_local"))
    fallback_port = v_int(p.get("fallback_port"), "پورت fallback", 0, 65535, 0)
    if fallback_port and fallback_port == https_port:
        raise ApiError("پورت fallback باید با پورت HTTPS فرق کند")
    token = str(p.get("cf_token") or "").strip()
    deps = ssl_deps()
    if not deps["nginx"] or not deps["certbot"]:
        raise ApiError("nginx و certbot نصب نیستند؛ اول دکمه «نصب پیش‌نیازها» را بزنید")
    if method == "cloudflare":
        if not deps["cloudflare"]:
            raise ApiError("افزونه کلادفلر certbot نصب نیست؛ دکمه «نصب پیش‌نیازها» را بزنید")
        if token:
            if not CF_TOKEN_RE.match(token):
                raise ApiError("توکن API کلادفلر نامعتبر است")
        elif not os.path.isfile(CF_INI):
            raise ApiError("توکن API کلادفلر را وارد کنید")
    log = []
    with LOCK:
        http80_owner = [o for o in _port_owner(80) if o not in ("nginx", "?")]
        for n_ in list_names():
            try:
                if any(tp == 80 and pr == "tcp" for tp, pr, k in _listener_ports(load_tunnel(n_))):
                    http80_owner.append("تانل " + n_)
            except ApiError:
                pass
        if (80, "tcp") in _client_ports():
            http80_owner.append("کلاینت " + _client_ports()[(80, "tcp")])
        if method == "http" and http80_owner:
            raise ApiError("برای روش HTTP پورت 80 باید آزاد باشد ولی برنامه %s آن را گرفته است؛ روش کلادفلر (DNS) را انتخاب کنید"
                           % ", ".join(http80_owner))
        if not http80_owner and 80 in (https_port, fallback_port):
            raise ApiError("پورت 80 برای HTTP ساده سایت (و تمدید گواهی) استفاده می‌شود؛ برای HTTPS یا fallback پورت دیگری بدهید")
        _check_site_port(https_port, domain, "HTTPS")
        if fallback_port:
            _check_site_port(fallback_port, domain, "fallback")
        if method == "cloudflare":
            if token:
                write_file(CF_INI, "dns_cloudflare_api_token = %s\n" % token, 0o600)
            if p.get("cf_dns"):
                tok = token or re.search(r"=\s*(\S+)", read_file(CF_INI)).group(1)
                log.append(cf_set_a_record(domain, ip, tok, bool(p.get("cf_proxied"))))
        else:
            got = resolve_ipv4(domain)
            if got != ip:
                raise ApiError("دامنه %s به %s اشاره می‌کند، نه %s. رکورد A دامنه را به IP این سرور بزنید (ابر نارنجی خاموش) و چند دقیقه بعد دوباره امتحان کنید"
                               % (domain, got or "هیچ IP", ip))
            log.append("%s → %s" % (domain, got))
        s_ = {"method": method, "ip": ip, "email": email, "template": template, "https_port": https_port,
              "https_local": https_local, "fallback_port": fallback_port, "http80": not http80_owner,
              "created": int(time.time())}
        write_site(domain, template)
        log.append("سایت (%s) ساخته شد" % template)
        have_cert = cert_info(domain)["exists"]
        nginx_apply(domain, s_, have_cert)
        cmd = ["certbot", "certonly", "--non-interactive", "--agree-tos", "--keep-until-expiring",
               "--cert-name", domain, "-d", domain,
               "--deploy-hook", "systemctl reload nginx"]
        cmd += ["-m", email] if email else ["--register-unsafely-without-email"]
        if method == "http":
            cmd += ["--webroot", "-w", os.path.join(WWW_DIR, domain)]
        else:
            cmd += ["--dns-cloudflare", "--dns-cloudflare-credentials", CF_INI,
                    "--dns-cloudflare-propagation-seconds", "30"]
        rc, out = run(cmd, timeout=300)
        if rc != 0 or not cert_info(domain)["exists"]:
            if domain not in sites_load() and not have_cert:   # new domain: leave nothing behind
                _site_cleanup(domain)
            raise ApiError("گرفتن گواهی ناموفق بود: %s" % (out.strip()[-500:] or "?"))
        log.append("گواهی Let's Encrypt برای %s گرفته شد" % domain)
        nginx_apply(domain, s_, True)
        log.append("سایت روی %s:%d با HTTPS بالا آمد" % ("127.0.0.1" if https_local else domain, https_port))
        sites = sites_load()
        sites[domain] = s_
        sites_save(sites)
    full, key = cert_paths(domain)
    return {"log": log, "fullchain": full, "privkey": key}


def _site_domain(p):
    d = str(p.get("domain") or "").strip().lower()
    if not DOMAIN_RE.match(d):
        raise ApiError("دامنه نامعتبر است")
    return d


def a_ssl_renew(p):
    d = _site_domain(p)
    cmd = ["certbot", "renew", "--cert-name", d, "--non-interactive", "--deploy-hook", "systemctl reload nginx"]
    if p.get("force"):
        cmd.append("--force-renewal")
    with LOCK:
        rc, out = run(cmd, timeout=300)
    if rc != 0:
        raise ApiError("تمدید ناموفق بود: %s" % out.strip()[-400:])
    return {"text": out.strip()[-1500:], "cert": cert_info(d)}


def a_ssl_template(p):
    d = _site_domain(p)
    t = p.get("template") if p.get("template") in SITE_TEMPLATES else None
    if not t:
        raise ApiError("قالب نامعتبر است")
    with LOCK:
        sites = sites_load()
        if d not in sites:
            raise ApiError("برای این دامنه سایتی ساخته نشده است")
        write_site(d, t)
        sites[d]["template"] = t
        sites_save(sites)
    return {}


def a_ssl_delete(p):
    d = _site_domain(p)
    with LOCK:
        sites = sites_load()
        conf = os.path.join(NGINX_DIR, "netifay-%s.conf" % d)
        try:
            os.remove(conf)
        except OSError:
            pass
        if shutil.which("nginx") and run(["nginx", "-t"])[0] == 0:
            run(["systemctl", "reload", "nginx"])
        root = os.path.join(WWW_DIR, d)
        if os.path.isdir(root) and os.path.realpath(root).startswith(os.path.realpath(WWW_DIR) + os.sep):
            shutil.rmtree(root, ignore_errors=True)
        if p.get("cert") and shutil.which("certbot"):
            rc, out = run(["certbot", "delete", "--cert-name", d, "--non-interactive"], timeout=60)
        sites.pop(d, None)
        sites_save(sites)
    return {}


def ssl_bundle(domain):
    full, key = cert_paths(domain)
    if not (os.path.isfile(full) and os.path.isfile(key)):
        raise ApiError("گواهی این دامنه پیدا نشد")
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tar:
        for src, name in ((full, "fullchain.pem"), (key, "privkey.pem")):
            with open(src, "rb") as f:
                data = f.read()
            ti = tarfile.TarInfo("%s/%s" % (domain, name))
            ti.size = len(data)
            ti.mtime = int(time.time())
            ti.mode = 0o600
            tar.addfile(ti, io.BytesIO(data))
    return buf.getvalue()


